package dev.jdtech.jellyfin.models

/**
 * Represents a physical hardware volume key event intercepted by an Activity or UI component.
 *
 * @property isUp True if the volume up button was pressed; false if volume down.
 * @property isRepeat True if this event was generated by a continuous button hold key-repeat.
 */
data class VolumeKeyEvent(
    val isUp: Boolean,
    val isRepeat: Boolean = false,
)
